(async()=>{'use strict';const D=SpaceFoxMarkerData,R=SpaceFoxMR,L=SpaceFoxLayoutData,$=s=>document.querySelector(s),selection=await(await fetch('final-selection.json')).json();let language='ru',key='falcon';
function demo(){const launch=L.launches[key],s=structuredClone(D.hero),t=L.strings[language],label=v=>({full:v,displayLabel:v});s.id='demo-'+key+'-'+language;s.language=language;s.fixture.model=key;s.fixture.point=launch.point;s.fixture.rocket=label(launch.rocket);s.fixture.operator=label(launch.operator);s.fixture.purpose=label(t[launch.purpose]);s.fixture.site=label(t[launch.country]+' · '+(language==='ru'?launch.siteRu:launch.site));s.countdown.displayLabel='T−'+Math.floor(launch.seconds/3600)+t.hour+' '+Math.floor(launch.seconds%3600/60)+t.minute;return s;}
function render(){const s=demo();$('#gallery').replaceChildren(...selection.candidates.map((c,i)=>{const card=document.createElement('article');card.className='card';const h=document.createElement('h2');h.textContent=selection.names[i];const box=document.createElement('div');box.className='preview';box.append(R.render(c,s));card.append(h,box);return card;}));$('#status').textContent='222 px — обзор; 390 px — исходный круг Forerunner 165. Браузерные проверки не измеряют чтение на запястье.';}
function menu(){const selected=key;$('#scene').replaceChildren(...Object.entries(L.launches).map(([id,l])=>{const o=document.createElement('option');o.value=id;o.textContent=l.rocket+' · '+(language==='ru'?l.siteRu:l.site);return o;}));$('#scene').value=selected;}
$('#scene').onchange=()=>{key=$('#scene').value;render();};$('#language').onclick=()=>{language=language==='ru'?'en':'ru';$('#language').textContent=language==='ru'?'English':'Русский';menu();render();};$('#size').onclick=()=>document.body.classList.toggle('native');$('#animate').onclick=()=>{document.querySelectorAll('.face').forEach(f=>f.classList.add('launch-demo'));$('#status').textContent='Демо анимации. Это не подтверждение реального старта.';setTimeout(()=>{document.querySelectorAll('.face').forEach(f=>f.classList.remove('launch-demo'));},1900);};await document.fonts.ready;menu();render();})();
